/**
 * PANEL MENU COMPOSITION — one composed array serves every surface.
 *
 * The desktop kebab (DockLeaf), the mobile commands sheet and the keyboard
 * matcher (DeskShortcuts) all consume the SAME composed array for the same
 * focused panel; a difference between surfaces is a bug, not a responsive
 * adaptation. The one projection rule lives here, not in the hosts: the
 * dock-level View menu is appended only where the host passes one — the
 * mobile sheet passes none because the panels drawer already projects those
 * commands on touch (show-or-open per type, Preferences), and the sheet must
 * never reach the structural toggle/split verbs.
 *
 * The dock-supplied "Panel" floor menu guarantees the array is never empty
 * (median registered payload is one item; Preview registers none), and gives
 * the panel's own commands — switch instance, close, about — one predictable
 * home instead of per-panel reinventions. `About <panel>` rides the floor so
 * Help is never a one-item menu; the host still owns the lazily loaded
 * InfoDialog and only lends `help.open`.
 *
 * Pure — no runes, node-testable.
 */

import type { MenuBarItem, MenuBarMenu } from '$lib/components/composites/menu-bar/types';
import type { PanelDefinition } from '$lib/desk/layout.types';

/** Declared once; the tab context menu prints it beside its own Close row. */
export const CLOSE_PANEL_SHORTCUT = 'Ctrl+W';

export interface PanelInstanceRef {
	id: string;
	label: string;
}

/** The panel's help entry — the host renders the dialog, the floor menu the row. */
export interface PanelHelpRef {
	title: string;
	open: () => void;
}

export interface ComposeMenusInput {
	/** Menus the panel registered (from the panel-menus registry). */
	registered: MenuBarMenu[];
	/** The panel the menu addresses (null → floor menu is empty). */
	panel: PanelDefinition | null;
	/** Open instances of the same panel TYPE, tree order, including `panel`. */
	instances: PanelInstanceRef[];
	/** The View menu for this projection (buildViewMenu output); null on the mobile sheet. */
	viewMenu: MenuBarMenu | null;
	actions: {
		focusPanel: (panelId: string) => void;
		/** Close one panel (hosts route it through the dock's unsaved-close guard). */
		closePanel: (panelId: string) => void;
		/** Close several at once — one guard prompt for the batch, not one per panel. */
		closePanels: (panelIds: string[]) => void;
	};
	/** When present, `About <title>` closes the floor menu. */
	help?: PanelHelpRef | null;
}

/** Compose the full menu array: [...registered, Panel floor, View?] — separators normalised, empty menus dropped. */
export function composePanelMenus(input: ComposeMenusInput): MenuBarMenu[] {
	const { registered, panel, instances, viewMenu, actions, help } = input;

	const floor: MenuBarMenu = { label: 'Panel', items: [] };
	if (panel) {
		const siblings = instances.filter((inst) => inst.id !== panel.id);
		if (siblings.length > 0) {
			for (const sibling of siblings) {
				floor.items.push({
					label: `Switch to ${sibling.label}`,
					icon: panel.icon,
					onSelect: () => actions.focusPanel(sibling.id),
				});
			}
			floor.items.push({ type: 'separator' });
		}
		// Ctrl+W lives here, not on the View menu: one row closes this panel, and
		// a panel that cannot be closed has no row for the chord to reach.
		if (panel.closable !== false) {
			floor.items.push({
				label: 'Close Panel',
				icon: 'i-lucide-x',
				shortcut: CLOSE_PANEL_SHORTCUT,
				onSelect: () => actions.closePanel(panel.id),
			});
		}
		if (siblings.length > 0) {
			floor.items.push({
				label: 'Close Other Instances',
				icon: 'i-lucide-x-circle',
				destructive: true,
				onSelect: () => actions.closePanels(siblings.map((sibling) => sibling.id)),
			});
		}
		if (help) {
			if (floor.items.length > 0) floor.items.push({ type: 'separator' });
			floor.items.push({ label: `About ${help.title}`, icon: 'i-lucide-info', onSelect: help.open });
		}
	}

	return [...registered, floor, ...(viewMenu ? [viewMenu] : [])]
		.map((menu) => ({ ...menu, items: withoutDanglingSeparators(menu.items) }))
		.filter((menu) => menu.items.length > 0);
}

/**
 * Conditional spreads routinely leave a separator first, last or doubled (the
 * editor's File menu on a saved post is `[separator, Export]`). Normalised here,
 * once, so no projection renders a rule the others drop.
 */
function withoutDanglingSeparators(items: MenuBarItem[]): MenuBarItem[] {
	const out: MenuBarItem[] = [];
	for (const item of items) {
		if (item.type === 'separator' && (out.length === 0 || out[out.length - 1].type === 'separator')) continue;
		out.push(item);
	}
	while (out.length > 0 && out[out.length - 1].type === 'separator') out.pop();
	return out;
}

/**
 * The About dialog's shortcut table, derived from the composed array so the
 * dialog can never list a chord the menu no longer shows (or miss one it does).
 * Returns '' when nothing declares a shortcut; otherwise a markdown table the
 * host appends to the panel's prose notes.
 */
export function shortcutTableMarkdown(menus: MenuBarMenu[]): string {
	const rows: string[] = [];
	for (const menu of menus) {
		for (const item of menu.items) {
			if (item.type === 'separator' || !item.shortcut || !item.label) continue;
			rows.push(`| ${item.shortcut} | ${menu.label} › ${item.label} |`);
		}
	}
	if (rows.length === 0) return '';
	return ['| Shortcut | Action |', '|---|---|', ...rows].join('\n');
}

/** Tree-ordered open instances of `panel`'s type — helper for compose callers. */
export function collectTypeInstances(
	openPanelIds: string[],
	panels: Record<string, PanelDefinition>,
	panelType: string | undefined,
): PanelInstanceRef[] {
	if (!panelType) return [];
	return openPanelIds
		.filter((id) => panels[id]?.type === panelType)
		.map((id) => ({ id, label: panels[id]?.label ?? id }));
}

/**
 * Typed pub/sub for cross-panel communication in the Desk.
 * Follows the same factory + context pattern as dock.state.svelte.ts.
 */

import { getContext, setContext } from 'svelte';

export interface DeskEvents {
	'editor:content': { content: string; type: string; metadata: Record<string, unknown> };
	'editor:document': { documentId: string; type: string } | null;
	'files:insert-image': {
		assetId: string;
		fileName: string;
		altText: string;
		downloadUrl: string;
		/** Unique nonce to deduplicate replayed events across panel remounts. */
		_nonce: string;
	};

	// AI-originated desk actions
	'ai:refresh_file': { fileId: string };
	/** The panel showing `fileId` answers `ai:refresh_file`: what it now shows, or that it could not reload. */
	'ai:file_refreshed': { fileId: string; version: number | null; ok: boolean };
	'ai:refresh_explorer': Record<string, never>;
}

export interface SubscribeOptions {
	/** Replay the last published payload immediately on subscribe. */
	replayLast?: boolean;
}

const DESK_BUS_CTX = Symbol('desk-bus');

export function createDeskBus() {
	const listeners = new Map<keyof DeskEvents, Set<(payload: DeskEvents[keyof DeskEvents]) => void>>();
	const lastPayload = new Map<keyof DeskEvents, unknown>();

	function publish<K extends keyof DeskEvents>(channel: K, payload: DeskEvents[K]): void {
		lastPayload.set(channel, payload);
		const subs = listeners.get(channel);
		if (subs) {
			for (const handler of subs) handler(payload);
		}
	}

	function subscribe<K extends keyof DeskEvents>(
		channel: K,
		handler: (payload: DeskEvents[K]) => void,
		options?: SubscribeOptions,
	): () => void {
		let subs = listeners.get(channel);
		if (!subs) {
			subs = new Set();
			listeners.set(channel, subs);
		}
		subs.add(handler as (payload: DeskEvents[keyof DeskEvents]) => void);

		// Replay last value if requested and available
		if (options?.replayLast && lastPayload.has(channel)) {
			handler(lastPayload.get(channel) as DeskEvents[K]);
		}

		return () => {
			subs?.delete(handler as (payload: DeskEvents[keyof DeskEvents]) => void);
			if (subs?.size === 0) listeners.delete(channel);
		};
	}

	return { publish, subscribe };
}

export type DeskBus = ReturnType<typeof createDeskBus>;

export function setDeskBusContext(): DeskBus {
	const bus = createDeskBus();
	setContext(DESK_BUS_CTX, bus);
	return bus;
}

export function getDeskBus(): DeskBus {
	return getContext<DeskBus>(DESK_BUS_CTX);
}

/**
 * Pure functions for dock layout tree operations.
 * All mutations produce new trees (immutable replacement).
 */

import type { DropZone, LayoutNode, LeafNode, PanelDefinition, SplitNode } from '$lib/desk/layout.types';

let counter = 0;

/** Generate a unique ID for layout nodes */
export function generateId(prefix: string): string {
	return `${prefix}-${Date.now()}-${counter++}`;
}

/** Find a node by ID in the tree */
export function findNode(root: LayoutNode, id: string): LayoutNode | null {
	if (root.id === id) return root;
	if (root.type === 'split') {
		return findNode(root.children[0], id) ?? findNode(root.children[1], id);
	}
	return null;
}

/** Find the parent split of a node by ID */
/** Find the leaf containing a panel ID */
export function findLeafWithPanel(root: LayoutNode, panelId: string): LeafNode | null {
	if (root.type === 'leaf') {
		return root.tabs.includes(panelId) ? root : null;
	}
	return findLeafWithPanel(root.children[0], panelId) ?? findLeafWithPanel(root.children[1], panelId);
}

/**
 * Replace a node in the tree by ID.
 * Returns null if the replacement is null and the target is root (empty tree).
 */
export function replaceNode(root: LayoutNode, targetId: string, replacement: LayoutNode | null): LayoutNode | null {
	if (root.id === targetId) return replacement;
	if (root.type === 'leaf') return root;

	const left = root.children[0].id === targetId ? replacement : replaceNode(root.children[0], targetId, replacement);
	const right = root.children[1].id === targetId ? replacement : replaceNode(root.children[1], targetId, replacement);

	// If one child was removed, promote the other
	if (left === null) return right;
	if (right === null) return left;

	return {
		...root,
		children: [left, right],
	};
}

/** Remove a panel from a leaf, returning updated leaf or null if empty */
export function removePanelFromLeaf(leaf: LeafNode, panelId: string): LeafNode | null {
	const tabs = leaf.tabs.filter((t) => t !== panelId);
	if (tabs.length === 0) return null;
	const activeTab = leaf.activeTab === panelId ? tabs[0] : leaf.activeTab;
	return { ...leaf, tabs, activeTab };
}

/** Add a panel as a tab in a leaf */
export function addPanelToLeaf(leaf: LeafNode, panelId: string): LeafNode {
	if (leaf.tabs.includes(panelId)) {
		return { ...leaf, activeTab: panelId };
	}
	return {
		...leaf,
		tabs: [...leaf.tabs, panelId],
		activeTab: panelId,
	};
}

/** Create a new split by wrapping an existing leaf with a new leaf */
export function splitLeaf(existingLeaf: LeafNode, newPanelId: string, zone: Exclude<DropZone, 'center'>): SplitNode {
	const newLeaf: LeafNode = {
		type: 'leaf',
		id: generateId('leaf'),
		tabs: [newPanelId],
		activeTab: newPanelId,
	};

	const direction: 'horizontal' | 'vertical' = zone === 'left' || zone === 'right' ? 'horizontal' : 'vertical';

	const first = zone === 'left' || zone === 'top' ? newLeaf : existingLeaf;
	const second = zone === 'left' || zone === 'top' ? existingLeaf : newLeaf;

	return {
		type: 'split',
		id: generateId('split'),
		direction,
		children: [first, second],
		sizes: [50, 50],
	};
}

/** Get tree depth */
export function getDepth(node: LayoutNode): number {
	if (node.type === 'leaf') return 0;
	return 1 + Math.max(getDepth(node.children[0]), getDepth(node.children[1]));
}

/** Resolve which drop zone the pointer is in, given a bounding rect */
export function resolveDropZone(
	rect: { left: number; top: number; width: number; height: number },
	clientX: number,
	clientY: number,
): DropZone {
	const relX = (clientX - rect.left) / rect.width;
	const relY = (clientY - rect.top) / rect.height;

	const edgeThreshold = 0.2;

	if (relY < edgeThreshold) return 'top';
	if (relY > 1 - edgeThreshold) return 'bottom';
	if (relX < edgeThreshold) return 'left';
	if (relX > 1 - edgeThreshold) return 'right';
	return 'center';
}

/** Collect all leaf nodes in the tree */
export function collectLeaves(node: LayoutNode): LeafNode[] {
	if (node.type === 'leaf') return [node];
	return [...collectLeaves(node.children[0]), ...collectLeaves(node.children[1])];
}

/** Collapse empty leaves from the tree, promoting siblings. Returns null if entire tree is empty. */
export function collapseEmptyLeaves(node: LayoutNode): LayoutNode | null {
	if (node.type === 'leaf') {
		return node.tabs.length === 0 ? null : node;
	}
	const left = collapseEmptyLeaves(node.children[0]);
	const right = collapseEmptyLeaves(node.children[1]);
	if (left === null && right === null) return null;
	if (left === null) return right;
	if (right === null) return left;
	return { ...node, children: [left, right] };
}

/** Check if a panel type exists anywhere in the tree */
export function hasPanelType(root: LayoutNode, panelType: string, panels: Record<string, PanelDefinition>): boolean {
	const leaves = collectLeaves(root);
	return leaves.some((leaf) => leaf.tabs.some((tabId) => panels[tabId]?.type === panelType));
}

/** All open panel IDs in layout order (left→right, top→bottom). */
export function collectPanelIds(root: LayoutNode): string[] {
	return collectLeaves(root).flatMap((leaf) => leaf.tabs);
}

/**
 * Next instance of a panel type after `currentId`, wrapping around.
 * Powers the mobile bar: tapping a type with several open instances
 * (e.g. two editors) cycles through them in layout order.
 */
export function nextPanelOfType(
	root: LayoutNode,
	panels: Record<string, PanelDefinition>,
	panelType: string,
	currentId: string | null,
): string | null {
	const ids = collectPanelIds(root).filter((id) => panels[id]?.type === panelType);
	if (ids.length === 0) return null;
	const currentIndex = currentId ? ids.indexOf(currentId) : -1;
	return ids[(currentIndex + 1) % ids.length];
}

