describe('activateTab idempotence', () => {
	it('re-activating the active tab does not reassign root', () => {
		const state = makeTwoLeafState();
		const rootBefore = state.root;
		state.activateTab('l2', 'p2');
		expect(state.root).toBe(rootBefore);
